def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my_last, op_last = history[-1]
    opp_def = sum(1 for _, o in history if o == 'D')
    my_def = sum(1 for m, _ in history if m == 'D')

    cons_opp_def = 0
    for o in reversed([h[1] for h in history]):
        if o == 'D':
            cons_opp_def += 1
        else:
            break

    if op_last == 'D':
        if cons_opp_def >= 5:
            return 'D'
        if opp_def > n * 0.7:
            return 'D'
        if my_last == 'D':
            return 'C'
        if opp_def <= n * 0.5:
            return 'C'
        return 'D'
    else:
        if n >= 2:
            recent_my = [m for m, _ in history[-3:]]
            recent_op = [o for _, o in history[-3:]]
            if all(m == 'D' for m in recent_my) and all(o == 'C' for o in recent_op):
                return 'D'
        return 'C'
